//! Byte-for-byte parity test against the original v1.1 JavaScript math.
//!
//! Reads `tests/fixtures/golden.json` (generated by `generate-golden.mjs`
//! from the v1.1 `src/calculations.js`) and checks that `percent-core`
//! produces the exact same `label`, `copyText`, and `error` strings for every
//! one of the 10,000+ cases.

use percent_core::{
    calculate_discount, calculate_original_value, calculate_percentage_change,
    calculate_percentage_of_total, calculate_percentage_portion, format_decimal, CalcResult,
};
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    f: String,
    a: Vec<String>,
    r: serde_json::Value,
}

fn parse_js_num(s: &str) -> f64 {
    match s {
        "NaN" => f64::NAN,
        "Infinity" => f64::INFINITY,
        "-Infinity" => f64::NEG_INFINITY,
        other => other
            .parse::<f64>()
            .unwrap_or_else(|e| panic!("bad float {other}: {e}")),
    }
}

#[test]
fn matches_v1_1_javascript_math_byte_for_byte() {
    let raw = include_str!("fixtures/golden.json");
    let cases: Vec<Case> = serde_json::from_str(raw).expect("valid golden.json");
    assert!(
        cases.len() > 10_000,
        "expected >10k golden cases, got {}",
        cases.len()
    );

    for (idx, case) in cases.iter().enumerate() {
        match case.f.as_str() {
            "formatDecimal" => {
                let x = parse_js_num(&case.a[0]);
                let expected = case.r.as_str().expect("string result");
                let actual = format_decimal(x);
                assert_eq!(actual, expected, "case #{idx} formatDecimal({})", case.a[0]);
            }
            "discount" => {
                let price = parse_js_num(&case.a[0]);
                let disc = parse_js_num(&case.a[1]);
                let actual = calculate_discount(price, disc);
                assert_eq!(
                    actual.label,
                    case.r["label"].as_str().unwrap(),
                    "case #{idx} discount({}, {}) label",
                    case.a[0],
                    case.a[1]
                );
                assert_eq!(
                    actual.copy_text,
                    case.r["copyText"].as_str().unwrap(),
                    "case #{idx} discount({}, {}) copyText",
                    case.a[0],
                    case.a[1]
                );
            }
            other => {
                let a = parse_js_num(&case.a[0]);
                let b = parse_js_num(&case.a[1]);
                let actual = match other {
                    "percentageChange" => calculate_percentage_change(a, b),
                    "percentageOfTotal" => calculate_percentage_of_total(a, b),
                    "percentagePortion" => calculate_percentage_portion(a, b),
                    "originalValue" => calculate_original_value(a, b),
                    _ => panic!("unknown function {other}"),
                };
                let want_ok = case.r["ok"].as_bool().unwrap();
                match (actual, want_ok) {
                    (CalcResult::Ok { label, .. }, true) => {
                        let want_label = case.r["label"].as_str().unwrap();
                        assert_eq!(
                            label, want_label,
                            "case #{idx} {other}({}, {})",
                            case.a[0], case.a[1]
                        );
                    }
                    (CalcResult::Err { error }, false) => {
                        let want_err = case.r["error"].as_str().unwrap();
                        assert_eq!(
                            error, want_err,
                            "case #{idx} {other}({}, {})",
                            case.a[0], case.a[1]
                        );
                    }
                    (got, _) => panic!(
                        "case #{idx} {other}({}, {}) ok mismatch: got {got:?}, want {}",
                        case.a[0], case.a[1], case.r
                    ),
                }
            }
        }
    }
}
